00522 template <typename T> inline void Check3( T minVal, T maxVal, T a)
00523 {
00524   CHECK( ( a > maxVal ) || ( a < minVal ), "ERROR: Range check " << minVal << " >= " << a << " <= " << maxVal << " failed" );
00525 }  
