00640 static inline int floorLog2(uint32_t x)
00641 {
00642   if (x == 0)
00643   {
00644     // note: ceilLog2() expects -1 as return value
00645     return -1;
00646   }
00647 #ifdef __GNUC__
00648   return 31 - __builtin_clz(x);
00649 #else
00650 #ifdef _MSC_VER
00651   unsigned long r = 0;
00652   _BitScanReverse(&r, x);
00653   return r;
00654 #else
00655   int result = 0;
00656   if (x & 0xffff0000)
00657   {
00658     x >>= 16;
00659     result += 16;
00660   }
00661   if (x & 0xff00)
00662   {
00663     x >>= 8;
00664     result += 8;
00665   }
00666   if (x & 0xf0)
00667   {
00668     x >>= 4;
00669     result += 4;
00670   }
00671   if (x & 0xc)
00672   {
00673     x >>= 2;
00674     result += 2;
00675   }
00676   if (x & 0x2)
00677   {
00678     x >>= 1;
00679     result += 1;
00680   }
00681   return result;
00682 #endif
00683 #endif
00684 }
00685 
00686 static inline int ceilLog2(uint32_t x)
00687 {
00688   return (x==0) ? -1 : floorLog2(x - 1) + 1;
00689 }
